  return {source,bindings:bindings.map(b=>({path:b.skill_path,skillId:b.skill_id,slug:b.slug,name:b.name,status:b.status,lastCommitSha:b.last_commit_sha,lastDigest:b.last_digest,lastVersionId:b.last_version_id})),runs:runs.rows.map(runRecord)};
 }
