  authorize(m.principal,"workspace:update");const config=gitSourceConfig(m.config),key=validateIdempotencyKey(m.idempotencyKey),hash=await hashIdempotentRequest(config),id=`source:${await hashIdempotentRequest({workspace:m.principal.workspaceId,actor:m.principal.actorId,key})}`;
