   // A creation audit has a deterministic resource ID; only emit once.
   const prior=await c.query("SELECT 1 FROM audit_events WHERE workspace_id=$1 AND resource_id=$2 AND event_type='skill_source.created'",[m.principal.workspaceId,id]);if(!prior.rowCount)await this.audit(c,m,id,"created");return record(row);});
 }
 async update(m:Mutation&{sourceId:string;expectedRevision:number;config:Record<string,unknown>;archived:boolean}) {
  authorize(m.principal,"workspace:update");const config=gitSourceConfig(m.config);
  if(!Number.isSafeInteger(m.expectedRevision)||typeof m.archived!=="boolean")throw new DomainError("VALIDATION_FAILED","Revision and archived state are required",400);
  return this.transaction(m,async c=>{const row=await this.row(m.principal,m.sourceId,c,true);if(row.revision!==m.expectedRevision || (row.sync_expires_at && row.sync_expires_at>new Date()))throw new DomainError("CONFLICT","Source changed or sync is running; reload first",409);
   if(config.repositoryUrl!==row.repository_url || config.path!==row.skill_path)throw new DomainError("CONFLICT","Create a new source to change repository or path scope",409);
   const r=await c.query<SourceRow>("UPDATE skill_sources SET ref=$3,ref_policy=$4,archived_at=CASE WHEN $5::boolean THEN COALESCE(archived_at,now()) ELSE NULL END,revision=revision+1,updated_at=now() WHERE workspace_id=$1 AND id=$2 RETURNING *",[m.principal.workspaceId,m.sourceId,config.ref,config.refPolicy,m.archived]);await this.audit(c,m,row.id,"updated",{archived:m.archived});const updated=r.rows[0];if(!updated)throw new DomainError("NOT_FOUND","Source was not found",404);return record(updated);});
 }
 private async bindings(p:Principal,id:string) {return (await this.pool.query<Binding>("SELECT b.*,s.slug,s.name,s.current_published_version_id,s.archived_at FROM skill_source_bindings b JOIN skills s ON s.workspace_id=b.workspace_id AND s.id=b.skill_id WHERE b.workspace_id=$1 AND b.source_id=$2 ORDER BY b.skill_path",[p.workspaceId,id])).rows;}
