  return this.transaction(m,async c=>{const s=await this.row(m.principal,m.sourceId,c,true);if(s.archived_at || (s.sync_expires_at && s.sync_expires_at>new Date()))throw new DomainError("CONFLICT","Source is archived or syncing",409);if(s.skill_path!==null && s.skill_path!==m.path)throw new DomainError("VALIDATION_FAILED","Path does not match this single-skill source",400);
