   const old=await c.query<{skill_id:string}>("SELECT skill_id FROM skill_source_bindings WHERE workspace_id=$1 AND source_id=$2 AND skill_path=$3",[m.principal.workspaceId,m.sourceId,m.path]);if(old.rows[0]) {if(old.rows[0].skill_id!==m.skillId)throw new DomainError("CONFLICT","Source path is already bound",409);return {changed:false};}
   try {await c.query("INSERT INTO skill_source_bindings(workspace_id,source_id,skill_path,skill_id,base_version_id) VALUES($1,$2,$3,$4,$5)",[m.principal.workspaceId,m.sourceId,m.path,m.skillId,skill.rows[0].current_published_version_id]);}catch(e){if(typeof e==="object" && e!==null && "code" in e && e.code==="23505")throw new DomainError("CONFLICT","Skill is already bound to a source",409);throw e;}
   await c.query("UPDATE skill_sources SET revision=revision+1,updated_at=now() WHERE id=$1",[s.id]);await this.audit(c,m,s.id,"bound",{skillId:m.skillId,path:m.path});return {changed:true};});
 }
 async preview(m:Mutation&{sourceId:string}) {
