   seen.add(item.path);const binding=bindings.find(b=>b.skill_path===item.path),base={path:item.path,slug:item.bundle?.skill.slug??null,digest:item.bundle?.digest??null,skillId:binding?.skill_id??null,baseVersionId:binding?.current_published_version_id??null};
   if(!item.bundle) {plan.push({...base,action:"error",message:item.error??"Invalid skill"});continue;}
   const slug=item.bundle.skill.slug, collision=slugs.has(slug);slugs.add(slug);
   if(collision || (!binding && catalog.rows.some(s=>s.slug===slug)) || (binding && (binding.slug!==slug || binding.archived_at || (binding.current_published_version_id!==binding.base_version_id && binding.current_published_version_id!==binding.last_version_id)))) {plan.push({...base,action:"conflict",message:"Slug conflict, archived skill, or manual changes require explicit resolution"});continue;}
