   const last=binding?.last_version_id?await this.pool.query<{status:string}>("SELECT status FROM skill_versions WHERE workspace_id=$1 AND id=$2",[m.principal.workspaceId,binding.last_version_id]):null;
   if(binding?.last_digest===item.bundle.digest && last?.rows[0]?.status==="rejected") {plan.push({...base,action:"conflict",message:"The last imported candidate was rejected"});continue;}
   plan.push({...base,action:binding?(binding.last_digest===item.bundle.digest?"unchanged":"changed"):"added",message:null});
  }
  for(const binding of bindings) if(!seen.has(binding.skill_path))plan.push({path:binding.skill_path,slug:binding.slug,digest:binding.last_digest,skillId:binding.skill_id,baseVersionId:binding.current_published_version_id,action:"missing",message:"Source path is missing or renamed; the existing skill is preserved"});
