       else {if(!entry.skillId || !entry.baseVersionId)throw new DomainError("CONFLICT","Binding lacks a published base",409);const version=await this.versions.createCandidate({...options,skillId:entry.skillId,baseVersionId:entry.baseVersionId,proposedBump:"patch",changeSummary:`Import ${source.repositoryUrl} at ${run.commit_sha}`});skillId=entry.skillId;versionId=version.id;}
